CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','analyst','admin')));
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY,"expiresAt" timestamptz NOT NULL,token text UNIQUE NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),"ipAddress" text,"userAgent" text,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_session_user ON session("userId");
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("providerId","accountId"));
CREATE TABLE IF NOT EXISTS verification(id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz DEFAULT now(),"updatedAt" timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS categories(id text PRIMARY KEY,color text NOT NULL DEFAULT '#38bdf8',icon text NOT NULL DEFAULT 'Globe');
CREATE TABLE IF NOT EXISTS news_sources(id text PRIMARY KEY,name text NOT NULL,type text NOT NULL,endpoint text NOT NULL,enabled boolean NOT NULL DEFAULT true,poll_interval integer NOT NULL DEFAULT 300,timeout_ms integer NOT NULL DEFAULT 20000,rate_limit integer NOT NULL DEFAULT 12,retries integer NOT NULL DEFAULT 3,last_success timestamptz,last_attempt timestamptz,status text NOT NULL DEFAULT 'pending',error text,license text NOT NULL);
CREATE TABLE IF NOT EXISTS raw_items(id text PRIMARY KEY,source_id text NOT NULL REFERENCES news_sources(id),external_id text NOT NULL,content_hash text NOT NULL,payload jsonb NOT NULL,fetched_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_id,external_id,content_hash));
CREATE TABLE IF NOT EXISTS articles(id text PRIMARY KEY,source_id text NOT NULL REFERENCES news_sources(id),external_id text NOT NULL,canonical_url text NOT NULL,title text NOT NULL,permitted_excerpt text NOT NULL DEFAULT '',language text NOT NULL DEFAULT 'en',published_at timestamptz NOT NULL,fetched_at timestamptz NOT NULL DEFAULT now(),content_hash text NOT NULL,UNIQUE(source_id,external_id));
CREATE TABLE IF NOT EXISTS events(id text PRIMARY KEY,title text NOT NULL,summary text NOT NULL,category text NOT NULL REFERENCES categories(id),status text NOT NULL DEFAULT 'developing',relevance_score double precision NOT NULL CHECK(relevance_score BETWEEN 0 AND 100),verification_status text NOT NULL DEFAULT 'source_reported',occurred_at timestamptz NOT NULL,first_detected_at timestamptz NOT NULL DEFAULT now(),last_updated_at timestamptz NOT NULL DEFAULT now(),source_id text NOT NULL REFERENCES news_sources(id),magnitude double precision,synthetic boolean NOT NULL DEFAULT false,search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple',title || ' ' || summary)) STORED);
CREATE INDEX IF NOT EXISTS events_search ON events USING GIN(search_vector);
CREATE INDEX IF NOT EXISTS events_time ON events(synthetic,occurred_at DESC);
CREATE INDEX IF NOT EXISTS events_category ON events(category,occurred_at DESC);
CREATE TABLE IF NOT EXISTS event_articles(event_id text REFERENCES events(id) ON DELETE CASCADE,article_id text REFERENCES articles(id) ON DELETE CASCADE,PRIMARY KEY(event_id,article_id));
CREATE TABLE IF NOT EXISTS event_locations(id text PRIMARY KEY,event_id text UNIQUE NOT NULL REFERENCES events(id) ON DELETE CASCADE,name text NOT NULL,country_code text,region text,latitude double precision CHECK(latitude BETWEEN -90 AND 90),longitude double precision CHECK(longitude BETWEEN -180 AND 180),precision text NOT NULL,geojson jsonb);
CREATE INDEX IF NOT EXISTS location_bounds ON event_locations(longitude,latitude);
CREATE TABLE IF NOT EXISTS event_versions(id bigserial PRIMARY KEY,event_id text NOT NULL REFERENCES events(id) ON DELETE CASCADE,recorded_at timestamptz NOT NULL DEFAULT now(),snapshot jsonb NOT NULL,content_hash text NOT NULL,UNIQUE(event_id,content_hash));
CREATE TABLE IF NOT EXISTS event_updates(id bigserial PRIMARY KEY,event_id text NOT NULL REFERENCES events(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),type text NOT NULL,description text NOT NULL);
CREATE TABLE IF NOT EXISTS event_claims(id text PRIMARY KEY,event_id text NOT NULL REFERENCES events(id) ON DELETE CASCADE,claim text NOT NULL,verification_status text NOT NULL,confidence double precision,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS claim_evidence(id text PRIMARY KEY,claim_id text NOT NULL REFERENCES event_claims(id) ON DELETE CASCADE,article_id text NOT NULL REFERENCES articles(id) ON DELETE CASCADE,evidence_type text NOT NULL,excerpt text NOT NULL);
CREATE TABLE IF NOT EXISTS entities(id text PRIMARY KEY,name text NOT NULL,type text NOT NULL,UNIQUE(name,type));
CREATE TABLE IF NOT EXISTS event_entities(event_id text REFERENCES events(id) ON DELETE CASCADE,entity_id text REFERENCES entities(id) ON DELETE CASCADE,PRIMARY KEY(event_id,entity_id));
CREATE TABLE IF NOT EXISTS event_relations(id text PRIMARY KEY,from_id text NOT NULL REFERENCES events(id) ON DELETE CASCADE,to_id text NOT NULL REFERENCES events(id) ON DELETE CASCADE,type text NOT NULL,explanation text NOT NULL,evidence_url text,score double precision,UNIQUE(from_id,to_id,type));
CREATE TABLE IF NOT EXISTS cluster_decisions(id bigserial PRIMARY KEY,left_id text NOT NULL,right_id text NOT NULL,decision text NOT NULL,scores jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS watchlists(id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,name text NOT NULL,keywords text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',source text NOT NULL DEFAULT '',enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS saved_events(user_id text REFERENCES "user"(id) ON DELETE CASCADE,event_id text REFERENCES events(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,event_id));
CREATE TABLE IF NOT EXISTS alerts(id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,watchlist_id text REFERENCES watchlists(id) ON DELETE CASCADE,event_id text NOT NULL REFERENCES events(id) ON DELETE CASCADE,type text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,watchlist_id,event_id,type));
CREATE TABLE IF NOT EXISTS notifications(id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,event_id text REFERENCES events(id) ON DELETE CASCADE,title text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),dedupe_key text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS notification_deliveries(id text PRIMARY KEY,notification_id text NOT NULL REFERENCES notifications(id) ON DELETE CASCADE,channel text NOT NULL,status text NOT NULL,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_preferences(user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,locale text NOT NULL DEFAULT 'en',theme text NOT NULL DEFAULT 'dark',alerts_enabled boolean NOT NULL DEFAULT true,quiet_start integer,quiet_end integer,timezone text NOT NULL DEFAULT 'UTC');
CREATE TABLE IF NOT EXISTS ingestion_jobs(id text PRIMARY KEY,source_id text NOT NULL REFERENCES news_sources(id),status text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,imported integer NOT NULL DEFAULT 0,unchanged integer NOT NULL DEFAULT 0,rejected integer NOT NULL DEFAULT 0,error text,duration_ms integer);
CREATE TABLE IF NOT EXISTS ai_analyses(id text PRIMARY KEY,event_id text REFERENCES events(id) ON DELETE CASCADE,provider text NOT NULL,model text NOT NULL,locale text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_usage(id bigserial PRIMARY KEY,user_id text REFERENCES "user"(id) ON DELETE SET NULL,provider text NOT NULL,model text NOT NULL,input_tokens integer,output_tokens integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS chat_messages(id bigserial PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,role text NOT NULL,content text NOT NULL,citations jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,user_id text REFERENCES "user"(id) ON DELETE SET NULL,action text NOT NULL,target text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS system_settings(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id bigserial PRIMARY KEY,type text NOT NULL,event_id text REFERENCES events(id) ON DELETE CASCADE,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
